export const LITE = new LiteCodec({
  types: TYPES,
  rpcs: RPCS,
  streams: STREAMS,
  request: "JSONRPCRequest",
  response: "JSONRPCResponse",
  subscribe: "WSSubscribeParams",
  subscribeResult: "WSSubscribeResult",
  unsubscribe: "WSUnsubscribeParams",
  /** Lite -> full key of a stream frame's envelope (the same for every stream). */
  frame: {
    s: "stream",
    s1: "selector",
    sn: "sequence_number",
    f: "feed",
    ps: "prev_sequence_number",
  },
  /** Lite -> full key of the HTTP error body (not a type). */
  httpError: {
    c: "code",
    m: "message",
    ri: "request_id",
    s: "status",
  },
});
